{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C14","C15","C03","C04","C11","C17","C05","C06","C16","C10","C27","C01","C02","C31","C36","C28"],
  "contradictory_card_ids": ["C24"],
  "prediction_basis_card_ids": ["C14","C15","C03","C04","C11","C17","C05","C06","C16","C10","C27","C01","C02","C31","C36","C28"],
  "claims": [
    {
      "claim": "The query is a saligenin beta2-agonist with a long lipophilic dichlorobenzyl ether N-substituent; the closest measured beta-agonist contexts show low oral bioavailability: salbutamol 7.2% and 11.4% in fasting subjects, bambuterol about 10%, and epanolol 5.85 ± 2.55% with food.",
      "card_ids": ["C14","C15","C03","C04","C11","C17"]
    },
    {
      "claim": "Additional transferable low-F contexts include DHPG absolute oral bioavailability 5.4 ± 1.6%, terfenadine <5% (L1 and L2), phenylephrine poor/low-transient oral bioavailability, and hydroxytyrosol 6.2 ± 1.1% in humans.",
      "card_ids": ["C05","C06","C16","C10","C27","C01","C02"]
    },
    {
      "claim": "New L3 batefenterol oral exposure data show that after 200 µg oral [14C]-batefenterol, parent batefenterol concentrations were non-quantifiable with pooled AUC0-t of 0.614 h·pgEq/mL, while total radioactivity AUC0-t was 387.8 pgEq·h/mL, indicating extensive first-pass metabolism and negligible parent oral exposure for a structurally related long-chain beta2 agonist.",
      "card_ids": ["C31","C36","C28"]
    },
    {
      "claim": "The remaining L3 AUC/Cmax records (guanfacine, amlodipine, 5-HMT, S-amlodipine) are oral exposure values without IV comparators or F endpoints; they do not affirmatively support F >= 20% for the query and are not transferable to this saligenin beta2-agonist.",
      "card_ids": ["C30","C29","C37","C33","C34","C35","C32","C38","C39"]
    },
    {
      "claim": "The only contradictory-direction card, C24, reports hydroxytyrosol as highly bioavailable in rats, but it is qualitative, rat-specific, and contradicted by the human L1 value of 6.2% in the same context.",
      "card_ids": ["C24"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C28","C29","C30","C31","C32","C33","C34","C35","C36","C37","C38","C39"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "Most L3 AUC/Cmax records lack IV comparators, so they cannot be converted into F values; only the batefenterol parent non-quantifiable result provides indirect first-pass evidence.",
    "The query's specific metabolic fate (e.g., CYP3A4 oxidation, phenol conjugation, O-dealkylation) is not directly measured in any cited card.",
    "C22 reports an I3C bioavailability range of 10-35% that spans the 20% threshold, leaving that context ambiguous.",
    "The long lipophilic dichlorobenzyl ether chain may alter permeability or first-pass metabolism relative to salbutamol/bambuterol; no vilanterol-specific card is present."
  ],
  "decision_summary": "Prediction remains low (F < 20%) with high confidence. Multiple transferable direct low oral-bioavailability outcomes for saligenin/beta-agonist and related contexts (salbutamol 7.2-11.4%, bambuterol ~10%, epanolol 5.85%, DHPG 5.4%, terfenadine <5%, phenylephrine poor, hydroxytyrosol 6.2%) affirmatively support F below 20%. New L3 batefenterol data strengthen this by showing negligible parent oral exposure after oral dosing in a structurally related long-chain beta2 agonist, while the other L3 AUC/Cmax records are exposure-only and neutral. The single contradictory rat hydroxytyrosol card is species-mismatched and outweighed."
}

